<div class="section-actions"><a href="<?= $link('/organizations/'.$organization['id'].'/passwords') ?>">← All passwords</a><?php if($canWrite): ?><a class="button secondary" href="<?= $link('/passwords/'.$entry['id'].'/edit') ?>">Edit password</a><?php endif; ?></div><section class="card"><span class="badge"><?= $entry['visibility']==='client'?'Client visible':'Internal only' ?></span><dl><dt>Username</dt><dd><?= $e($entry['username']) ?></dd><?php if($entry['url']): ?><dt>URL</dt><dd><a href="<?= $e($entry['url']) ?>" target="_blank" rel="noopener noreferrer"><?= $e($entry['url']) ?></a></dd><?php endif; ?><dt>Configuration</dt><dd><?php if($configuration): ?><a href="<?= $link('/records/'.$configuration['id']) ?>"><?= $e($configuration['title']) ?></a><?php else: ?>Standalone<?php endif; ?></dd><dt>Notes</dt><dd><?= nl2br($e($entry['notes'])) ?></dd></dl><h2>Password</h2><?php if($secret===null): ?><p>••••••••••••</p><form method="post" action="<?= $link('/passwords/'.$entry['id'].'/reveal') ?>"><?= $csrf ?><button class="button">Reveal password</button></form><p class="help">Revealing a password is recorded in audit history.</p><?php else: ?><pre class="revealed-secret" id="revealed-password"><?= $e($secret) ?></pre><button class="button secondary" type="button" data-copy-secret="revealed-password">Copy password</button><a class="button secondary" href="<?= $link('/passwords/'.$entry['id']) ?>">Hide password</a><?php endif; ?></section><?php if($canWrite): ?><details class="card danger-zone"><summary>Archive password</summary><form method="post" action="<?= $link('/passwords/'.$entry['id'].'/archive') ?>" data-confirm="Archive this password?"><?= $csrf ?><button class="button danger">Archive password</button></form></details><?php endif; ?>
